const config = {
  "previewFeatures": [],
  "clientVersion": "7.9.0",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================================\n// UNIFIED SCHEMA\n// Merges: web app schema (AI-assisted verification pipeline) +\n//         mobile app schema (marketplace booking/quote/escrow/payment engine)\n// See accompanying notes for merge decisions and open questions.\n// ============================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // Connection URLs now live in prisma.config.ts (Prisma ORM 7+)\n}\n\n// ============================================================================\n// ENUMS\n// ============================================================================\n\nenum Role {\n  CLIENT\n  WORKER\n  ADMIN\n}\n\nenum TokenType {\n  ACCESS\n  REFRESH\n  EMAIL_VERIFICATION\n  PASSWORD_RESET\n}\n\nenum BookingStatus {\n  PENDING\n  ACCEPTED\n  REJECTED\n  IN_PROGRESS\n  QUOTE_SUBMITTED\n  QUOTE_APPROVED\n  DISPUTED\n  COMPLETED\n  CANCELLED\n}\n\nenum QuoteStatus {\n  PENDING\n  SUBMITTED\n  APPROVED\n  DISPUTED\n}\n\nenum PaymentStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REFUNDED\n}\n\nenum EscrowStatus {\n  HELD\n  RELEASED\n  REFUNDED\n}\n\nenum PaymentMethodType {\n  GCASH\n  MAYA\n  CARD\n  BANK_TRANSFER\n  CASH\n}\n\nenum KYCStatus {\n  PENDING\n  SUBMITTED\n  APPROVED\n  REJECTED\n}\n\nenum KycDocumentType {\n  GOVERNMENT_ID_FRONT\n  GOVERNMENT_ID_BACK\n  SELFIE\n  RESUME\n  CERTIFICATION\n  NBI_CLEARANCE\n  BARANGAY_CLEARANCE\n  POLICE_CLEARANCE\n  CEDULA\n}\n\nenum KycDocumentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum ContractType {\n  WORKER_SERVICE_AGREEMENT\n  CLIENT_USER_AGREEMENT\n}\n\nenum NotificationType {\n  BOOKING_REQUEST\n  BOOKING_ACCEPTED\n  BOOKING_REJECTED\n  BOOKING_CANCELLED\n  BOOKING_RESCHEDULED\n  BOOKING_COMPLETED\n  PAYMENT_RECEIVED\n  PAYMENT_REFUNDED\n  ADDON_ADDED\n  REVIEW_RECEIVED\n  MESSAGE_RECEIVED\n  VERIFICATION_EMAIL\n  PASSWORD_RESET\n  QUOTE_SUBMITTED\n  QUOTE_APPROVED\n  QUOTE_DISPUTED\n  VERIFICATION_SUBMITTED\n  VERIFICATION_APPROVED\n  VERIFICATION_REJECTED\n}\n\n// ============================================================================\n// USER & AUTH\n// ============================================================================\n\nmodel User {\n  id       String  @id @default(cuid())\n  email    String  @unique\n  phone    String?\n  password String\n  fullName String\n  role     Role\n\n  isVerified              Boolean @default(false) // basic email/phone verification, not KYC\n  avatar                  String?\n  notificationPreferences Json?\n\n  // Soft delete\n  isDeleted Boolean   @default(false)\n  deletedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  clientProfile        ClientProfile?\n  workerProfile        WorkerProfile?\n  addresses            UserAddress[]\n  sentMessages         Message[]             @relation(\"sender\")\n  receivedMessages     Message[]             @relation(\"receiver\")\n  bookingsAsClient     Booking[]             @relation(\"client\")\n  bookingsAsWorker     Booking[]             @relation(\"worker\")\n  reviews              Review[]\n  notifications        Notification[]\n  authTokens           AuthToken[]\n  verificationRequests VerificationRequest[]\n  contractAcceptances  ContractAcceptance[]\n\n  @@index([email])\n  @@index([role])\n  @@index([isDeleted])\n}\n\nmodel UserAddress {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  label     String?\n  street    String\n  city      String\n  state     String?\n  zipCode   String?\n  isDefault Boolean @default(false)\n\n  // Soft delete\n  isDeleted Boolean   @default(false)\n  deletedAt DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([userId])\n  @@index([userId, isDefault])\n}\n\nmodel AuthToken {\n  id        String    @id @default(cuid())\n  userId    String\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n  token     String    @unique\n  type      TokenType\n  expiresAt DateTime\n  createdAt DateTime  @default(now())\n\n  @@index([userId])\n  @@index([token])\n}\n\n// ============================================================================\n// PROFILES\n// ============================================================================\n\nmodel ClientProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  address String?\n  city    String?\n  state   String?\n  zipCode String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  paymentMethods SavedPaymentMethod[]\n\n  @@index([userId])\n}\n\nmodel WorkerProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  bio          String?\n  rating       Float   @default(5.0)\n  totalReviews Int     @default(0)\n\n  // Availability & Capacity\n  isAvailable       Boolean @default(true)\n  maxConcurrentJobs Int     @default(2)\n  activeJobCount    Int     @default(0)\n  availableDays     Int[]   @default([1, 2, 3, 4, 5]) // 0=Sun, 1=Mon ... 6=Sat\n  serviceAreaRadius Int     @default(30) // in kilometers\n\n  // Location\n  address String?\n  city    String?\n  state   String?\n  zipCode String?\n\n  // KYC — denormalized snapshot; source of truth is VerificationRequest\n  kycStatus      KYCStatus @default(PENDING)\n  kycSubmittedAt DateTime?\n  kycApprovedAt  DateTime?\n\n  // Resume file URL (raw file)\n  resumeUrl String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  serviceTypes      ServiceType[]\n  certifications    Certification[]\n  reviews           Review[]\n  resumeParseResult ResumeParseResult?\n\n  @@index([userId])\n  @@index([kycStatus])\n  @@index([isAvailable])\n}\n\n// ============================================================================\n// KYC & VERIFICATION\n// Web's AI-review pipeline (VerificationRequest) now acts as the umbrella\n// submission; each document previously modeled separately in mobile's flat\n// KycDocument now hangs off the request it was submitted for, so the AI\n// fields (aiStatus/aiSummary/aiConfidence) apply to the whole submission and\n// every document in it is traceable back to that review.\n// ============================================================================\n\nmodel VerificationRequest {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type                String // e.g. \"WORKER_ONBOARDING\", \"CERTIFICATION_ADD\", \"REVERIFICATION\"\n  status              KYCStatus @default(PENDING)\n  rejectionReason     String?\n  adminOverrideReason String?\n  reviewedById        String?\n  reviewedAt          DateTime?\n\n  // AI-assisted review (carried over from web schema)\n  aiStatus     String?\n  aiSummary    String?\n  aiConfidence Float?\n  aiError      String?\n  aiReviewedAt DateTime?\n\n  submittedAt DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  documents KycDocument[]\n\n  @@index([status])\n  @@index([userId])\n}\n\nmodel KycDocument {\n  id                    String              @id @default(cuid())\n  verificationRequestId String\n  verificationRequest   VerificationRequest @relation(fields: [verificationRequestId], references: [id], onDelete: Cascade)\n\n  documentType KycDocumentType\n  fileName     String?\n  originalName String?\n  fileUrl      String\n  fileSize     Int?\n  mimeType     String?\n\n  status          KycDocumentStatus @default(PENDING)\n  rejectionReason String?\n  reviewedById    String?\n  reviewedAt      DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([verificationRequestId, documentType])\n  @@index([status])\n}\n\nmodel ResumeParseResult {\n  id              String        @id @default(cuid())\n  workerProfileId String        @unique\n  workerProfile   WorkerProfile @relation(fields: [workerProfileId], references: [id], onDelete: Cascade)\n\n  rawText           String?\n  parsedSkills      String[]\n  yearsOfExperience Int?\n  masteryLevel      String?\n  tradeCategory     String?\n  summary           String?\n\n  parsedAt  DateTime @default(now())\n  modelUsed String   @default(\"claude-sonnet-4-6\")\n\n  @@index([workerProfileId])\n}\n\nmodel Certification {\n  id              String        @id @default(cuid())\n  workerProfileId String\n  workerProfile   WorkerProfile @relation(fields: [workerProfileId], references: [id], onDelete: Cascade)\n\n  title       String\n  issuer      String\n  issueDate   DateTime\n  expiryDate  DateTime?\n  documentUrl String\n\n  // Verification tracking\n  verificationStatus KycDocumentStatus @default(PENDING)\n  rejectionReason    String?\n  reviewedAt         DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([workerProfileId])\n  @@index([verificationStatus])\n}\n\n// ============================================================================\n// LEGAL\n// ============================================================================\n\nmodel ContractAcceptance {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  contractType    ContractType\n  contractVersion String       @default(\"1.0\")\n  acceptedAt      DateTime     @default(now())\n  ipAddress       String?\n  userAgent       String?\n\n  @@index([userId, contractType])\n}\n\n// ============================================================================\n// SERVICES\n// ============================================================================\n\nmodel ServiceType {\n  id          String  @id @default(cuid())\n  name        String\n  description String?\n  basePrice   Float\n  isActive    Boolean @default(true)\n\n  // Relations\n  workers WorkerProfile[]\n  tasks   ServiceTask[]\n\n  @@unique([name])\n}\n\nmodel ServiceTask {\n  id            String      @id @default(cuid())\n  serviceTypeId String\n  serviceType   ServiceType @relation(fields: [serviceTypeId], references: [id], onDelete: Cascade)\n\n  name          String\n  description   String?\n  basePrice     Float\n  durationHours Float\n  isActive      Boolean @default(true)\n\n  // Relations\n  bookings Booking[]\n\n  @@index([serviceTypeId])\n}\n\n// ============================================================================\n// BOOKINGS\n// ============================================================================\n\nmodel Booking {\n  id String @id @default(cuid())\n\n  // Parties — workerId is nullable to support open/unassigned marketplace\n  // requests (web's behavior) that later get claimed or matched to a worker.\n  clientId String\n  client   User    @relation(\"client\", fields: [clientId], references: [id], onDelete: Cascade)\n  workerId String?\n  worker   User?   @relation(\"worker\", fields: [workerId], references: [id], onDelete: Cascade)\n\n  // Service\n  serviceType            String\n  serviceTaskId          String?\n  serviceTask            ServiceTask? @relation(fields: [serviceTaskId], references: [id])\n  description            String\n  estimatedDurationHours Float?\n\n  // Scheduling\n  scheduledDate  DateTime\n  scheduledTime  String?\n  completionDate DateTime?\n\n  // Status\n  status BookingStatus @default(PENDING)\n\n  // Pricing — initial estimate\n  estimatedPrice Float\n  tip            Float? @default(0)\n\n  // Quote lifecycle\n  quoteStatus   QuoteStatus?\n  laborCost     Float?\n  materialsCost Float?\n  quotedAt      DateTime?\n  quoteNotes    String?\n  approvedAt    DateTime?\n  disputeReason String?\n\n  // Inspection fee\n  inspectionFeeCharged Boolean @default(false)\n  inspectionFeeAmount  Float?\n\n  // Final\n  finalPrice Float?\n\n  // Location\n  location String\n  city     String\n  notes    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  payment Payment?\n  review  Review?\n  addOns  BookingAddOn[]\n\n  // NOTE: only enforceable while workerId is set — see merge notes.\n  @@unique([workerId, scheduledDate, scheduledTime], name: \"worker_slot_unique\")\n  @@index([clientId, status])\n  @@index([workerId, status])\n  @@index([scheduledDate])\n  @@index([status])\n}\n\nmodel BookingAddOn {\n  id        String  @id @default(cuid())\n  bookingId String\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  name  String\n  price Float\n\n  @@index([bookingId])\n}\n\n// ============================================================================\n// PAYMENTS\n// ============================================================================\n\nmodel Payment {\n  id        String  @id @default(cuid())\n  bookingId String  @unique\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  // Amounts\n  subtotal Float\n  tip      Float @default(0)\n\n  // Commission\n  commissionRate   Float @default(0.10)\n  commissionAmount Float\n\n  // Withholding tax (BIR compliance for professional fees)\n  withholdingTaxRate   Float @default(0.05)\n  withholdingTaxAmount Float\n\n  // Worker receives\n  workerPayout Float\n\n  // Total charged to client\n  totalAmount Float\n\n  // Status\n  status       PaymentStatus @default(PENDING)\n  escrowStatus EscrowStatus  @default(HELD)\n  releasedAt   DateTime?\n\n  // PayMongo references\n  paymongoPaymentId String?\n  paymongoSourceId  String?\n\n  // Payment method used\n  methodType        PaymentMethodType\n  accountIdentifier String? // masked GCash number, last 4 of card, etc.\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([bookingId])\n  @@index([status])\n  @@index([escrowStatus])\n}\n\nmodel SavedPaymentMethod {\n  id              String        @id @default(cuid())\n  clientProfileId String\n  clientProfile   ClientProfile @relation(fields: [clientProfileId], references: [id], onDelete: Cascade)\n\n  type              PaymentMethodType\n  accountIdentifier String? // masked — last 4 digits or masked phone number\n  label             String? // e.g. \"My GCash\", \"Work Card\"\n  isDefault         Boolean           @default(false)\n\n  createdAt DateTime @default(now())\n\n  @@index([clientProfileId])\n}\n\n// ============================================================================\n// REVIEWS\n// ============================================================================\n\nmodel Review {\n  id        String  @id @default(cuid())\n  bookingId String  @unique\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  workerId String\n  worker   WorkerProfile @relation(fields: [workerId], references: [id], onDelete: Cascade)\n\n  clientId String\n  client   User   @relation(fields: [clientId], references: [id], onDelete: Cascade)\n\n  rating  Float // 1.0 to 5.0\n  comment String?\n\n  createdAt DateTime @default(now())\n\n  @@index([workerId])\n  @@index([clientId])\n}\n\n// ============================================================================\n// MESSAGING\n// ============================================================================\n\nmodel Message {\n  id         String @id @default(cuid())\n  senderId   String\n  sender     User   @relation(\"sender\", fields: [senderId], references: [id], onDelete: Cascade)\n  receiverId String\n  receiver   User   @relation(\"receiver\", fields: [receiverId], references: [id], onDelete: Cascade)\n\n  content String\n  isRead  Boolean   @default(false)\n  readAt  DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@index([senderId])\n  @@index([receiverId])\n  @@index([createdAt])\n}\n\n// ============================================================================\n// NOTIFICATIONS\n// ============================================================================\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  type      NotificationType\n  title     String\n  message   String\n  relatedId String?\n  isRead    Boolean          @default(false)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([isRead])\n  @@index([userId, isRead])\n}\n"
}

